#include <vector>
#include <algorithm>
#include <climits>

using namespace std;

class Solution {
public:
    int minOperations(vector<int>& nums) {
        int n = nums.size();
        if (n <= 1) return 0;

        int pos = 0;
        while (pos < n && nums[pos] != 0) {
            pos++;
        }

        bool forward = true;
        for (int i = 0; i < n; ++i) {
            if (nums[(pos + i) % n] != i) {
                forward = false;
                break;
            }
        }

        bool backward = true;
        for (int i = 0; i < n; ++i) {
            if (nums[(pos - i + n) % n] != i) {
                backward = false;
                break;
            }
        }

        if (!forward && !backward) return -1;

        int ans = INT_MAX;
        if (forward) {
            if (pos == 0) {
                ans = min(ans, 0);
            } else {
                ans = min(ans, min(pos, n - pos + 2));
            }
        }
        if (backward) {
            ans = min(ans, min(n - pos, ((pos + 1) % n) + 1));
        }

        return ans;
    }
};
